import{_ as o,o as d,c,ai as i}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"层叠样式 CSS","description":"","frontmatter":{},"headers":[],"relativePath":"disciplines/frontend/basic/css.md","filePath":"disciplines/frontend/basic/css.md","lastUpdated":1787215730000}'),l={name:"disciplines/frontend/basic/css.md"};function a(t,e,r,p,n,s){return d(),c("div",null,[...e[0]||(e[0]=[i(`<h1 id="层叠样式-css" tabindex="-1">层叠样式 CSS <a class="header-anchor" href="#层叠样式-css" aria-label="Permalink to &quot;层叠样式 CSS&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="视觉格式化模型" tabindex="-1">视觉格式化模型 <a class="header-anchor" href="#视觉格式化模型" aria-label="Permalink to &quot;视觉格式化模型&quot;">​</a></h2><h3 id="盒模型" tabindex="-1">盒模型 <a class="header-anchor" href="#盒模型" aria-label="Permalink to &quot;盒模型&quot;">​</a></h3><p>描述元素布局的矩形框(<code>位置、尺寸、属性</code>)，由内容、内边距、边框、外边距等区域组成。</p><br><p>内容区域(<code>content</code>): 盒模型的具体内容。</p><p>内边距区域(<code>padding</code>): 盒模型的内容填充物。</p><p>边框区域(<code>border</code>): 盒模型的外层表皮套件。</p><p>外边距区域(<code>margin</code>): 盒模型对外保持的距离；垂直方向可能产生塌陷现象，以重叠距离后的最大值为准。</p><br><p><strong>特别注意</strong></p><p>盒模型有<code>2</code>种，分别为<code>标准盒模型</code>和<code>怪异盒模型</code>。</p><ul><li><p>标准盒模型(<code>content-box</code>): 宽高属性仅对应内容区域，不包括填充区域和外边距区域；浏览器默认盒模型。</p></li><li><p>怪异盒模型(<code>border-box</code>): 宽高属性包含内容区域、内边距和边框。</p></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">标准盒模型的宽高</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 内容区域边界范围。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">怪异盒模型的宽高</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 内容区域边界</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 内边距边界</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 边框边界等范围之和。</span></span></code></pre></div><br><h3 id="包含块" tabindex="-1">包含块 <a class="header-anchor" href="#包含块" aria-label="Permalink to &quot;包含块&quot;">​</a></h3><p>用于定位偏移和尺寸计算的参考价矩形框。</p><p>常态下以最近块盒模型的内容区域作为包含块；但在定位场景，包含块指向基于定位的盒模型填充区域。</p><br><table tabindex="0"><thead><tr><th>案例场景</th><th>包含块指向</th></tr></thead><tbody><tr><td>常规场景: <code>static</code>、<code>relative</code>、<code>sticky</code>、<code>float</code></td><td><code>最近块级的内容区域</code></td></tr><tr><td>定位场景: <code>fixed</code></td><td><code>视口区域</code></td></tr><tr><td>定位场景: <code>absolute</code></td><td><code>最近定位的填充区域或根元素的填充元素</code></td></tr><tr><td>定位场景: <code>absolute</code>、<code>fixed</code> + 祖先含<code>transform</code>、<code>filter</code>、<code>perspective</code>属性设置</td><td><code>直接锁定该祖先的填充区域</code></td></tr></tbody></table><br><h3 id="格式化上下文" tabindex="-1">格式化上下文 <a class="header-anchor" href="#格式化上下文" aria-label="Permalink to &quot;格式化上下文&quot;">​</a></h3><p>描述盒模型所在区域的排列布局方式。</p><br><p><strong>编排规则</strong></p><ul><li><p>块盒与行盒不能相邻，且内容必须在行盒内。</p></li><li><p>在构建布局树过程中，浏览器会通过匿名行盒或块盒自动补全布局编排。</p></li></ul><br><h4 id="行级格式化上下文" tabindex="-1">行级格式化上下文 <a class="header-anchor" href="#行级格式化上下文" aria-label="Permalink to &quot;行级格式化上下文&quot;">​</a></h4><p>行盒模型按水平方向一行编排。</p><p>而行盒的高度由行内最高元素决定，并可通过样式规则<code>vertical-align</code>设置基线对齐方式。</p><br><h4 id="块级格式化上下文" tabindex="-1">块级格式化上下文 <a class="header-anchor" href="#块级格式化上下文" aria-label="Permalink to &quot;块级格式化上下文&quot;">​</a></h4><p>独立的渲染区域；块盒模型独占一行并按垂直方向编排。</p><br><p><strong>构成条件</strong></p><ul><li><p><code>float</code>不为<code>none</code>。</p></li><li><p><code>overflow</code>不为<code>visible</code>。</p></li><li><p><code>display</code>为<code>flow-root</code>。</p></li><li><p><code>position</code>相对定位或绝对定位。</p></li><li><p>行块盒(<code>inline-block</code>)、表格布局(<code>table-cell</code>、<code>table-caption</code>)、弹性(<code>flex</code>)、网格(<code>grid</code>)等布局。</p></li><li><p>新特性支持: <code>contain: layout | paint | strict | size</code>。</p></li><li><p>浏览器差异: <code>will-change: transform | opacity</code>。</p></li></ul><br><p><strong>核心作用</strong></p><ul><li><p>解决垂直方向<code>margin</code>塌陷。</p></li><li><p>清除浮动<code>(父元素高度塌陷)</code>。</p></li><li><p>防止文本环绕浮动元素。</p></li><li><p>内部布局隔离，不影响外部。</p></li></ul><br><h4 id="弹性格式化上下文" tabindex="-1">弹性格式化上下文 <a class="header-anchor" href="#弹性格式化上下文" aria-label="Permalink to &quot;弹性格式化上下文&quot;">​</a></h4><p>独立的渲染区域，内部元素布局不影响外部；需通过<code>display: flex | inline-flex</code>声明。</p><p>核心: 根据<code>主轴</code>、<code>交叉轴</code>实现的布局方式。</p><br><p><strong>特别注意</strong></p><ul><li><p>容器子项块化，无法改变<code>display</code>设置。</p></li><li><p>不支持浮动布局<code>(float)</code>、基线对齐<code>(vertical-align)</code>、多列布局<code>(column)</code>；即设置无效化。</p></li><li><p>子项默认<code>min-width: auto</code>可能导致内容溢出，可设置<code>min-width: 0</code>解决。</p></li></ul><br><p><strong>容器属性</strong></p><ul><li><p>方向换行: <code>flex-flow</code>，规定主轴方向以及是否换行展示。</p></li><li><p>对齐方式: <code>justify-content</code>、<code>align-items</code>，规定单行基于主轴、交叉轴的对齐方式。</p></li><li><p>多行对齐: <code>align-content</code>，规定多行基于交叉轴的对齐方式。</p></li></ul><br><p><strong>子项属性</strong></p><ul><li><p>编排占比: <code>flex</code>，规定子项的扩展<code>(grow: 分配但不占)</code>、收缩<code>(shrink: 不够可压缩)</code>、固定<code>(basis: 基础宽度值)</code>等弹性占位比例值；默认<code>flex: 0 1 auto</code>。</p></li><li><p>编排次序: <code>order</code>，数值越小，越靠前排列。</p></li><li><p>独立对齐: <code>align-self</code>，基于交叉轴独立设置子项的对齐方式，会覆盖容器<code>align-items</code>属性规则。</p></li></ul><br><h4 id="网格格式化上下文" tabindex="-1">网格格式化上下文 <a class="header-anchor" href="#网格格式化上下文" aria-label="Permalink to &quot;网格格式化上下文&quot;">​</a></h4><p>独立的渲染区域，内部元素布局不影响外部；需通过<code>display: grid | inline-grid</code>声明。</p><p>核心: 根据<code>网格编排</code>、<code>子项放置</code>实现的布局方式。</p><br><p><strong>特别注意</strong></p><ul><li><p>容器子项块化，无法改变<code>display</code>设置。</p></li><li><p>不支持浮动布局<code>(float)</code>、基线对齐<code>(vertical-align)</code>、多列布局<code>(column)</code>；即设置无效化。</p></li><li><p>子项默认<code>min-width: auto</code>可能导致内容溢出，可设置<code>min-width: 0</code>解决。</p></li></ul><br><p><strong>网格编排</strong></p><ul><li><p>网格单位: <code>fr</code>，规定占有剩余空间的等分份数。</p></li><li><p>语法函数: 批量重复定义<code>repeat(次数, 取值)</code>、自适应取值<code>minmax(小值, 大值)</code>。</p></li><li><p>填充方式: <code>auto-fill</code>、<code>auto-fit</code>。</p></li><li><p>显式网格: 数值声明<code>grid-template</code>，命名声明<code>grid-template-areas</code>。</p></li><li><p>隐式网格: <code>grid-auto-rows</code>、<code>grid-auto-columns</code>、<code>grid-auto-flow</code>，规定隐式网格行列尺寸和空白填充方式。</p></li><li><p>网格间距: <code>gap</code>，规定网格轨道间距。</p></li><li><p>容器内对齐: <code>justify-content</code>、<code>align-content</code>；可简写为<code>place-content: 列对齐 行对齐</code>。</p></li><li><p>子项内对齐: <code>justify-items</code>、<code>align-items</code>；可简写为<code>place-items: 列对齐 行对齐</code>。</p></li></ul><br><p><strong>子项放置</strong></p><ul><li><p>数值子项定位: <code>grid-column</code>、<code>grid-row</code>，通过网格线编号或<code>span 跨数</code>进行定位。</p></li><li><p>命名子项定位: <code>grid-area</code>，通过命名网格区域<code>(配合 grid-template-areas)</code>进行定位。</p></li><li><p>单子项内对齐: <code>justify-self</code>、<code>align-self</code>；可简写为<code>place-self</code>。</p></li><li><p>编排次序: <code>order</code>，数值越小，越靠前排列。</p></li><li><p>编排层级: <code>z-index</code>，数值越大，越靠前排列。</p></li></ul><br><h2 id="样式属性语法" tabindex="-1">样式属性语法 <a class="header-anchor" href="#样式属性语法" aria-label="Permalink to &quot;样式属性语法&quot;">​</a></h2><h3 id="样式选择器" tabindex="-1">样式选择器 <a class="header-anchor" href="#样式选择器" aria-label="Permalink to &quot;样式选择器&quot;">​</a></h3><h4 id="锚点选择器" tabindex="-1">锚点选择器 <a class="header-anchor" href="#锚点选择器" aria-label="Permalink to &quot;锚点选择器&quot;">​</a></h4><ul><li><p><code>通配符</code>选择器: 描述所有元素；通过<code>*</code>映射。</p></li><li><p><code>id</code>选择器: 描述全局唯一的元素；通过<code>id</code>定义，通过<code>#id</code>映射。</p></li><li><p><code>tag</code>选择器: 描述具有相同标签的所有元素；直接通过<code>标签名</code>映射。</p></li><li><p><code>attr</code>选择器: 描述具有相同属性特性的所有元素，直接通过<code>标签名[属性=属性值]</code>映射。</p></li><li><p><code>class</code>选择器: 描述一组相关的元素，通过<code>class</code>定义；通过<code>.class</code>映射。</p></li><li><p><code>伪类</code>选择器: 描述处于特定状态的所有元素，直接通过<code>:状态</code>映射。</p></li><li><p><code>伪元素</code>选择器: 描述特定部分的所有元素；直接通过<code>::伪元素</code>映射。</p></li></ul><br><h4 id="层级选择器" tabindex="-1">层级选择器 <a class="header-anchor" href="#层级选择器" aria-label="Permalink to &quot;层级选择器&quot;">​</a></h4><ul><li><p><code>后代</code>选择器: 描述里层具有指定元素的所有元素，通过<code>父元素 后代元素</code>映射。</p></li><li><p><code>子代</code>选择器: 描述里层首层指定元素的所有元素，通过<code>父元素 &gt; 子代元素</code>映射。</p></li><li><p><code>相邻往后兄弟</code>选择器: 描述当前紧跟往后的首个指定元素，通过<code>当前元素 + 紧邻且指定元素</code>映射。</p></li><li><p><code>同级往后兄弟</code>选择器: 描述当前往后同级的所有指定元素，通过<code>当前元素 ~ 同级且指定元素</code>映射。</p></li></ul><br><h4 id="选择器权重" tabindex="-1">选择器权重 <a class="header-anchor" href="#选择器权重" aria-label="Permalink to &quot;选择器权重&quot;">​</a></h4><p>可通过<code>0000</code>四位表示法记录选择器权重；权重越高，优先级越高。</p><br><ul><li><p>特殊梯队: 浏览器渲染强制性规则<code>(flex、grid 子项块化)</code>。</p></li><li><p>第一梯队: <code>!important &gt; 行内样式 &gt; id选择器</code>。</p></li><li><p>第二梯队: <code>class选择器 &gt; attr选择器 &gt; 伪类选择器</code>。</p></li><li><p>第三梯队: <code>tag选择器 &gt; 伪元素选择器</code>。</p></li></ul><br><h3 id="属性规则表" tabindex="-1">属性规则表 <a class="header-anchor" href="#属性规则表" aria-label="Permalink to &quot;属性规则表&quot;">​</a></h3><p><code>CSS</code>规则的意义: 通过选择器匹配对应<code>HTML</code>标签，并设置样式规则<code>(位置、尺寸、属性)</code>，使得标签内容展示更加美观。</p><br><h4 id="模型属性" tabindex="-1">模型属性 <a class="header-anchor" href="#模型属性" aria-label="Permalink to &quot;模型属性&quot;">​</a></h4><ul><li><code>box-sizing</code>: 设置盒模型的渲染方式；默认<code>content-box</code>，但推荐<code>border-box</code>。</li></ul><br><h4 id="轮廓属性" tabindex="-1">轮廓属性 <a class="header-anchor" href="#轮廓属性" aria-label="Permalink to &quot;轮廓属性&quot;">​</a></h4><ul><li><p><code>outline</code>: 盒模型轮廓。</p></li><li><p><code>opacity</code>: 盒模型透明度。</p></li><li><p><code>box-shadow</code>: 盒模型阴影。</p></li><li><p><code>border-radius</code>: 盒模型圆角半径。</p></li></ul><br><h4 id="块盒属性" tabindex="-1">块盒属性 <a class="header-anchor" href="#块盒属性" aria-label="Permalink to &quot;块盒属性&quot;">​</a></h4><ul><li><p><code>width</code>: 盒模型宽度；需考虑盒模型渲染方式。</p></li><li><p><code>height</code>: 盒模型高度；需考虑盒模型渲染方式。</p></li><li><p><code>min-width</code>: 盒模型最小宽度；需考虑盒模型渲染方式。</p></li><li><p><code>min-height</code>: 盒模型最小高度；需考虑盒模型渲染方式。</p></li><li><p><code>max-width</code>: 盒模型最大宽度；需考虑盒模型渲染方式。</p></li><li><p><code>max-height</code>: 盒模型最大高度；需考虑盒模型渲染方式。</p></li><li><p><code>border</code>: 盒模型外部包装套壳；需考虑盒模型渲染方式。</p></li><li><p><code>padding</code>: 盒模型内容填充距离；需考虑盒模型渲染方式。</p></li><li><p><code>content</code>: 盒模型实际内容；需考虑盒模型渲染方式。</p></li><li><p><code>background</code>: 盒模型底部背景；需考虑盒模型渲染方式。</p></li><li><p><code>margin</code>: 盒模型外部保持距离。</p></li><li><p><code>overflow</code>: 盒模型内容溢出处理。</p></li><li><p><code>visibility</code>: 盒模型占位且显隐。</p></li></ul><br><h4 id="行盒属性" tabindex="-1">行盒属性 <a class="header-anchor" href="#行盒属性" aria-label="Permalink to &quot;行盒属性&quot;">​</a></h4><ul><li><p><code>font</code>: 文本字体属性。</p></li><li><p><code>color</code>: 文本颜色属性。</p></li><li><p><code>text-align</code>: 文本水平对齐。</p></li><li><p><code>line-height</code>: 文本纵向对齐。</p></li><li><p><code>vertical-align</code>: 文本基线对齐。</p></li><li><p><code>word-spacing</code>: 文本单词间距。</p></li><li><p><code>letter-spacing</code>: 文本字符间距。</p></li><li><p><code>writing-mode</code>: 文本书写方向。</p></li><li><p><code>text-indent</code>: 文本首行缩进。</p></li><li><p><code>white-space</code>: 换行空白处理。</p></li><li><p><code>text-overflow</code>: 文本溢出省略。</p></li><li><p><code>text-decoration</code>: 文本装饰属性。</p></li><li><p><code>text-transform</code>: 文本大小写转换。</p></li><li><p><code>list-style</code>: 文本列表样式。</p></li><li><p><code>clip</code>: 图片裁剪区域。</p></li><li><p><code>object-fit</code>: 图片、视频变换适配。</p></li><li><p><code>object-position</code>: 图片、视频变换适配纵横位置。</p></li></ul><br><h4 id="堆叠属性" tabindex="-1">堆叠属性 <a class="header-anchor" href="#堆叠属性" aria-label="Permalink to &quot;堆叠属性&quot;">​</a></h4><ul><li><code>z-index</code>: 盒模型在<code>Z轴</code>的堆叠次序。</li></ul><br><h4 id="浮动属性" tabindex="-1">浮动属性 <a class="header-anchor" href="#浮动属性" aria-label="Permalink to &quot;浮动属性&quot;">​</a></h4><p>使浮动元素脱离文档流，影响后续元素布局；可通过<code>clear</code>清除浮动影响。</p><ul><li><p><code>float</code>: 盒模型浮动方式。</p></li><li><p><code>clear</code>: 清除浮动。</p></li></ul><br><h4 id="定位属性" tabindex="-1">定位属性 <a class="header-anchor" href="#定位属性" aria-label="Permalink to &quot;定位属性&quot;">​</a></h4><p>通过精准定位，使定位元素脱离文档流。</p><ul><li><p><code>position</code>: 盒模型定位方式。</p></li><li><p><code>top</code>、<code>bottom</code>: 盒模型垂直位置。</p></li><li><p><code>left</code>、<code>right</code>: 盒模型水平位置。</p></li></ul><br><h4 id="弹性属性" tabindex="-1">弹性属性 <a class="header-anchor" href="#弹性属性" aria-label="Permalink to &quot;弹性属性&quot;">​</a></h4><br><h5 id="容器属性" tabindex="-1">容器属性 <a class="header-anchor" href="#容器属性" aria-label="Permalink to &quot;容器属性&quot;">​</a></h5><ul><li><p>方向换行: <code>flex-flow</code>，规定主轴方向以及是否换行展示。</p></li><li><p>对齐方式: <code>justify-content</code>、<code>align-items</code>，规定单行基于主轴、交叉轴的对齐方式。</p></li><li><p>多行对齐: <code>align-content</code>，规定多行基于交叉轴的对齐方式。</p></li><li><p>行列间距: <code>gap</code>，规定行间距和列间距。</p></li></ul><br><h5 id="子项属性" tabindex="-1">子项属性 <a class="header-anchor" href="#子项属性" aria-label="Permalink to &quot;子项属性&quot;">​</a></h5><ul><li><p>编排占比: <code>flex</code>，规定子项的扩展<code>(grow: 分配但不占)</code>、收缩<code>(shrink: 不够可压缩)</code>、固定<code>(basis: 基础宽度值)</code>等弹性占位比例值；默认<code>flex: 0 1 auto</code>。</p></li><li><p>编排次序: <code>order</code>，数值越小，越靠前排列。</p></li><li><p>独立对齐: <code>align-self</code>，基于交叉轴独立设置子项的对齐方式，会覆盖容器<code>align-items</code>属性规则。</p></li></ul><br><h4 id="网格属性" tabindex="-1">网格属性 <a class="header-anchor" href="#网格属性" aria-label="Permalink to &quot;网格属性&quot;">​</a></h4><br><h5 id="网格编排" tabindex="-1">网格编排 <a class="header-anchor" href="#网格编排" aria-label="Permalink to &quot;网格编排&quot;">​</a></h5><ul><li><p>网格单位: <code>fr</code>，规定占有剩余空间的等分份数。</p></li><li><p>语法函数: 批量重复定义<code>repeat(次数, 取值)</code>、自适应取值<code>minmax(小值, 大值)</code>。</p></li><li><p>填充方式: <code>auto-fill</code>、<code>auto-fit</code>。</p></li><li><p>显式网格: 数值声明<code>grid-template</code>，命名声明<code>grid-template-areas</code>。</p></li><li><p>隐式网格: <code>grid-auto-rows</code>、<code>grid-auto-columns</code>、<code>grid-auto-flow</code>，规定隐式网格行列尺寸和空白填充方式。</p></li><li><p>网格间距: <code>gap</code>，规定网格轨道间距。</p></li><li><p>容器内对齐: <code>justify-content</code>、<code>align-content</code>；可简写为<code>place-content: 列对齐 行对齐</code>。</p></li><li><p>子项内对齐: <code>justify-items</code>、<code>align-items</code>；可简写为<code>place-items: 列对齐 行对齐</code>。</p></li></ul><br><h5 id="子项放置" tabindex="-1">子项放置 <a class="header-anchor" href="#子项放置" aria-label="Permalink to &quot;子项放置&quot;">​</a></h5><ul><li><p>数值子项定位: <code>grid-column</code>、<code>grid-row</code>，通过网格线编号或<code>span 跨数</code>进行定位。</p></li><li><p>命名子项定位: <code>grid-area</code>，通过命名网格区域<code>(配合 grid-template-areas)</code>进行定位。</p></li><li><p>单子项内对齐: <code>justify-self</code>、<code>align-self</code>；可简写为<code>place-self</code>。</p></li><li><p>编排次序: <code>order</code>，数值越小，越靠前排列。</p></li><li><p>编排层级: <code>z-index</code>，数值越大，越靠前排列。</p></li></ul><br><h4 id="变形属性" tabindex="-1">变形属性 <a class="header-anchor" href="#变形属性" aria-label="Permalink to &quot;变形属性&quot;">​</a></h4><ul><li><code>transform</code>: 盒模型的变换操作<code>(旋转、缩放、平移、倾斜)</code>；注意复合变形过程，往后书写优先执行。</li></ul><br><h4 id="动画属性" tabindex="-1">动画属性 <a class="header-anchor" href="#动画属性" aria-label="Permalink to &quot;动画属性&quot;">​</a></h4><ul><li><p><code>@keyframes</code>: 逐帧动画，可细粒控制<code>(0%~100%)</code>关键帧顺序行为。</p></li><li><p><code>animation</code>: 并行执行动画组内容<code>(动画名、时长、缓动函数、延迟、次数、方向、填充模式、播放状态)</code>；优先等待延迟，再执行动画组。</p></li><li><p><code>transition</code>: 动画过渡效果<code>(属性、时间、缓动函数、延迟)</code>。</p></li></ul><br><h4 id="事件属性" tabindex="-1">事件属性 <a class="header-anchor" href="#事件属性" aria-label="Permalink to &quot;事件属性&quot;">​</a></h4><ul><li><p><code>cursor</code>: 鼠标指针形状。</p></li><li><p><code>pointer-events</code>: 事件交互样式。</p></li></ul><br><h3 id="层叠计算规则" tabindex="-1">层叠计算规则 <a class="header-anchor" href="#层叠计算规则" aria-label="Permalink to &quot;层叠计算规则&quot;">​</a></h3><p>在渲染阶段<code>(层叠样式计算)</code>过程中，样式规则解析器会将<code>初始值</code>、<code>指定值</code>、经过系列过程，转换为<code>计算值</code>和<code>应用值</code>。</p><br><h4 id="确定明确值" tabindex="-1">确定明确值 <a class="header-anchor" href="#确定明确值" aria-label="Permalink to &quot;确定明确值&quot;">​</a></h4><p>将<code>初始值</code>、<code>指定值</code>、经过系列查找过程，转换为可被计算的明确值。</p><br><h4 id="样式值层叠" tabindex="-1">样式值层叠 <a class="header-anchor" href="#样式值层叠" aria-label="Permalink to &quot;样式值层叠&quot;">​</a></h4><p>根据样式规则来源，选择器权重，书写源次序等层叠覆盖，确定部分最终样式。</p><br><h4 id="样式值继承" tabindex="-1">样式值继承 <a class="header-anchor" href="#样式值继承" aria-label="Permalink to &quot;样式值继承&quot;">​</a></h4><p>存在样式值未设置指定，会判断样式规则继承能力，从而逐层向上查找继承值。</p><br><h4 id="样式值默认" tabindex="-1">样式值默认 <a class="header-anchor" href="#样式值默认" aria-label="Permalink to &quot;样式值默认&quot;">​</a></h4><p>存在样式值未设置指定，不存在样式规则继承能力，则自动沿用浏览器默认样式。</p><h2 id="图层分层堆叠" tabindex="-1">图层分层堆叠 <a class="header-anchor" href="#图层分层堆叠" aria-label="Permalink to &quot;图层分层堆叠&quot;">​</a></h2><p>渲染主线程采用一套复杂策略对整个布局进行图层分层，使得在未来某一图层发生变化，仅处理该图层，而不影响其他图层；从而提高渲染效率。目的是减少重绘，并利用<code>GPU</code>加速渲染。</p><br><table tabindex="0"><thead><tr><th>图层分层要素</th><th>属性、操作具象</th></tr></thead><tbody><tr><td>堆叠上下文</td><td><code>z-index</code></td></tr><tr><td>盒模型透明度</td><td><code>opacity</code></td></tr><tr><td>盒模型变换操作</td><td><code>transform</code></td></tr><tr><td>盒模型动画组</td><td><code>animation</code></td></tr><tr><td>指定计算并优化</td><td><code>will-change</code></td></tr><tr><td>滚动条持续触发</td><td><code>scroll</code>事件</td></tr></tbody></table>`,150)])])}const b=o(l,[["render",a]]);export{u as __pageData,b as default};
